  ('ff57e849-07b6-5e75-975d-4b06493692fc', null, (select id from public.skills where slug = 'write-g8-sentence-structure'), null, 'medium',
   $q$Read the sentences: "Leilani packed healthy snacks for the trip. Such as apple slices, almonds, and cheese sticks." Which revision fixes the fragment?$q$, $q$[{"text":"Leilani packed healthy snacks for the trip; such as apple slices, almonds, and cheese sticks.","is_correct":false,"misconception_token":"semicolon-before-fragment"},{"text":"Leilani packed healthy snacks for the trip. Such as apple slices, almonds, and also cheese sticks.","is_correct":false,"misconception_token":"reworded-fragment-still"},{"text":"Leilani packed healthy snacks for the trip. Such as: apple slices, almonds, and cheese sticks.","is_correct":false,"misconception_token":"colon-does-not-fix-fragment"},{"text":"Leilani packed healthy snacks for the trip, such as apple slices, almonds, and cheese sticks.","is_correct":true}]$q$::jsonb, $q$Leilani packed healthy snacks for the trip, such as apple slices, almonds, and cheese sticks.$q$, $q$A "such as" phrase gives examples and has no subject or verb, so it must attach to the sentence with a comma. A semicolon cannot fix it because the words after the semicolon still are not a complete clause.$q$, 'draft', null)
