  ('335ff8e1-d135-5671-8c7f-66d59ed719cc', null, (select id from public.skills where slug = 'write-g8-sentence-structure'), null, 'medium',
   $q$Read the sentences: "The power went out. We lit candles. Grandpa told stories." Which choice combines them into one compound-complex sentence (two independent clauses and at least one dependent clause)?$q$, $q$[{"text":"The power went out, we lit candles, and Grandpa told stories.","is_correct":false,"misconception_token":"compound-not-compound-complex"},{"text":"When the power went out, we lit candles while Grandpa told stories.","is_correct":false,"misconception_token":"complex-not-compound-complex"},{"text":"When the power went out, we lit candles, and Grandpa told stories.","is_correct":true},{"text":"The power went out, and we lit candles, Grandpa told stories.","is_correct":false,"misconception_token":"comma-splice-created"}]$q$::jsonb, $q$When the power went out, we lit candles, and Grandpa told stories.$q$, $q$"When the power went out" is a dependent clause, and "we lit candles" and "Grandpa told stories" are two independent clauses joined by ", and." The "while" version has only one independent clause, so it is complex, not compound-complex.$q$, 'draft', null)
