  ('85f093d9-955d-58ea-a79c-bbc183129701', null, (select id from public.skills where slug = 'write-g8-sentence-structure'), null, 'hard',
   $q$Which sentence contains a comma splice?$q$, $q$[{"text":"After nodding at the players, the coach blew her whistle, and practice began.","is_correct":false,"misconception_token":"introductory-phrase-as-splice"},{"text":"The coach nodded; then, smiling at the team, she blew her whistle.","is_correct":false,"misconception_token":"semicolon-as-splice"},{"text":"The coach, who had seen the drill before, nodded and then blew her whistle.","is_correct":false,"misconception_token":"compound-predicate-as-splice"},{"text":"The coach, who had seen the drill before, nodded, then she blew her whistle.","is_correct":true}]$q$::jsonb, $q$The coach, who had seen the drill before, nodded, then she blew her whistle.$q$, $q$"The coach nodded" and "then she blew her whistle" are both independent clauses, and "then" is an adverb, so the comma alone creates a splice. The "nodded and then blew" version has one subject with two verbs, so it is a single clause.$q$, 'draft', null)
