-- Passage wg8-writing-with-evidence-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('8ca33250-10a4-57a2-af28-2f3bad0a991c', 'wg8-writing-with-evidence-p05', (select id from public.skills where slug = 'write-g8-writing-with-evidence'), null,
        '6-8', $q$Draft: What Rest Days Do$q$, $q$(1) In "Rest Days Win Races," Kofi Mensah argues that young runners improve faster when they take regular rest days. (2) Mensah explains that muscles grow stronger during rest, not during the workout itself. (3) He describes a study in which two groups of middle school runners trained for eight weeks. (4) One group ran every day, and the other rested two days a week. (5) Mensah reports that the group that rested "cut an average of forty seconds from their mile times," while the other group improved by only twelve seconds. (6) ____.

(7) Mensah also points out that rest protects runners from injury. (8) In the study, four runners in the everyday group hurt their shins, but only one runner in the rest group did. (9) My friend Ji-woo runs every day and has never been hurt. (10) Mensah's evidence shows that rest helps runners both get faster and stay healthy.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
insert into public.generated_questions
  (id, template_id, skill_id, sat_alignment, difficulty, stem, choices, correct_answer, solution, status, passage_id)
values
  ('2a0936da-d191-5e0c-a8aa-55480be4a948', null, (select id from public.skills where slug = 'write-g8-writing-with-evidence'), null, 'easy',
   $q$Why should the writer remove sentence 9?$q$, $q$[{"text":"It repeats the study results already given in sentence 8.","is_correct":false,"misconception_token":"misreads-repetition"},{"text":"It quotes Mensah directly without explaining what the words mean.","is_correct":false,"misconception_token":"misidentifies-problem"},{"text":"It is one personal example from outside the article, and it weakens the analysis.","is_correct":true},{"text":"It is the claim of the draft, so it should come first in the paragraph.","is_correct":false,"misconception_token":"misidentifies-claim"}]$q$::jsonb, $q$It is one personal example from outside the article, and it weakens the analysis.$q$, $q$Ji-woo is the writer's friend, not part of Mensah's article, and one person's experience works against the point being made. Sentence 9 contains no quotation from Mensah.$q$, 'draft', '8ca33250-10a4-57a2-af28-2f3bad0a991c')
